window.__posterData({"id": "liam-seigelstrand", "name": "Liam Seigelstrand", "folder": "Week3_Poster_Seigelstrand_Liam.zip", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "//process Comment: \n//Step 1: In accordance of the instructions Claude (ai) was told to refactor without changing functionality, claude then organized the code in four parts. 1.Data in arrays. Where the panels, text labels and decorative dots are now stored in arrays. 2.Setup(), which is unchanged. 3. A short draw() that calls functions in order. 4. The function are each doing one job. Together they contain what my old longer draw function did. The refactored code was 119 line instead of 142 lines. I wrote a lot of the code for design elements one by one, claude put all of these in arrays something i wanted to do before, but didnt fully know how.\n\n//step 2: For step 2 i asked claude to make the speakers look nicer, since the spaeaker idea is the main selling point of my poster, by adding screw in each corner a sourrounding cirle around the center woofer, a black background color, aswell as replacing the full color wheel spectrum with just colors within the overall design(pink,purple,blue) the speakers look a lot more speaker-like. I also told claude to keep the dimensions the same except for the woofer, which a wanted a bit smaller aswell as contained within the outer woofer circle. While i didnt ask for it, claude made the speaker box lines change color according to mouse position just like the center woofer, it looks nice so decided to keep it.\n\n//Step 3: For step 3 i simply used \"Suggest and implement 1 additional feature to this poster, something that YOU think is fun, such as an animation loop, interactive component, or something else. Use your best judgement given the current style and aesthetic.\" Here, claude gave me the ripples coming out of the speakers (sound waves) which i thought was perfect, minimal changes was asked for after though, first the ripple came out behind the speaker boxes, instead i asked claud to put them in front, with the woofer as the source, and before they only activated after click, instead i wanted it to keep going while holding mous button.\n\n\n// x,y coordinates and size for the four speaker circles\nconst circleX = [110, 490, 110, 490];\nconst circleY = [350, 350, 470, 470];\n \n// speaker colors (HSB hues): the mouse slides from blue (200) through purple to pink (320) this is so instead of a rainbow, the speakers are set to a specific color, a function i wanted but wasn't sure how to achieve before, hue_min & hue_max make a lot of sense though.\nconst HUE_MIN = 200;\nconst HUE_MAX = 320;\n \n// screw positions in the corners of each speaker, relative to its center, this is part of step one, where i wanted the speakers to be more detailed and speaker looking, instead of just four boxes with a pulsating circle in it, Claude gave them the same color changing function as the woofer, which i didnt ask for, but i liked it so i kept it.\nconst SCREW_OFFSETS = [[-48, -48], [48, -48], [-48, 48], [48, 48]];\n \n// bass-drop ripples: clicking or holding the mouse adds them, and each expands from the woofer of all four speakers, making it look like the woofers are pushing out sound waves.\nlet ripples = [];\nconst RIPPLE_START = 37;  // radius where a ripple begins: the edge of the woofer\nconst RIPPLE_MAX = 260;   // radius where a ripple has faded out and is removed\nconst RIPPLE_SPEED = 3;   // pixels the ripple grows per frame\nconst RIPPLE_LAG = 14;    // how far the accent ring trails behind the main ring\nconst RIPPLE_INTERVAL = 20; // while the mouse is held, a new ripple starts every 20 frames\nlet lastRippleFrame = 0;  // the frame when the last ripple started\n \n// the three colored panels: [x, y, width, height, color when mouse is pressed]\nconst panels = [\n  [40, 40, 520, 150, 'rgb(140 117 255)'],\n  [40, 200, 520, 395, 'rgb(255 133 245)'],\n  [40, 605, 520, 150, 'rgb(202 146 232)'],\n];\nconst PANEL_IDLE_COLOR = 'rgb(129 117 163)';\n \n// the decorative dots next to the big RAVE text: [x, y, diameter]\nconst dots = [\n  [70, 80, 20], [70, 120, 25], [70, 160, 20],\n  [530, 80, 20], [530, 120, 25], [530, 160, 20],\n];\n \n// all the text on the poster: [string, x, y, size]\nconst labels = [\n  ['RAVE', 300, 160, 150],        // big top text\n  ['RAVE', 110, 240, 50],         // small, top left\n  ['RAVE', 110, 280, 50],         // small, bottom left\n  ['RAVE', 490, 240, 50],         // small, top right\n  ['RAVE', 490, 280, 50],         // small, bottom right\n  ['LIGHT PARTY', 300, 585, 70],  // middle bottom\n  ['18/11', 300, 240, 50],        // middle top\n  ['2026', 300, 280, 50],\n  ['Lights', 300, 720, 130],      // bottom text\n];\n \n// stores my uploaded image\nlet img;\n \n// loads my uploaded image so its ready\nasync function setup() {\n  img = await loadImage('/Assets/Rave Pic.jpg');\n  createCanvas(600, 800);\n  colorMode(HSB); // hue, saturation, brightness (like a color wheel)\n}\n\n \nfunction draw() {\n  background('rgb(0 0 0)');\n \n  drawCornerLines();\n  drawPanels();\n  spawnRipplesWhileHeld();\n  image(img, 177, 285, 245, 245); // image position and size\n  drawText();\n  drawSpeakers();\n  drawRipples(); // on the very front, so the waves pass over the speakers, image and text\n  drawDots();\n}\n \n// the corner lines outside the 3 rectangles\nfunction drawCornerLines() {\n  stroke('rgb(255 255 255)');\n  strokeWeight(4);\n  line(20, 20, 20, 50);     // top left\n  line(20, 20, 50, 20);\n  line(580, 20, 580, 50);   // top right\n  line(580, 20, 550, 20);\n  line(20, 780, 20, 750);   // bottom left\n  line(20, 780, 50, 780);\n  line(580, 750, 580, 780); // bottom right\n  line(580, 780, 550, 780);\n}\n \n// the 3 panels: colored while the mouse is pressed, greyish purple otherwise\nfunction drawPanels() {\n  noStroke();\n  for (const [x, y, w, h, pressedColor] of panels) {\n    fill(mouseIsPressed ? pressedColor : PANEL_IDLE_COLOR);\n    rect(x, y, w, h);\n  }\n}\n \n// all text uses the same settings, only string, position and size change\nfunction drawText() {\n  fill('rgb(255 255 255)');\n  textAlign(CENTER);\n  textFont('Courier New');\n  for (const [label, x, y, size] of labels) {\n    textSize(size);\n    text(label, x, y);\n  }\n}\n \n// four speakers; mouseX controls the color (blue to pink), mouseY controls how far the woofer \"pumps\"\nfunction drawSpeakers() {\n  const mainHue = getHue();\n  const accentHue = getAccentHue(mainHue);\n  const pump = map(mouseY, 0, height, 20, 100);\n \n  for (let i = 0; i < circleX.length; i++) {\n    drawSpeaker(circleX[i], circleY[i], mainHue, accentHue, pump);\n  }\n}\n \n// one speaker: cabinet, corner screws and a centered woofer (big speaker with rings)\nfunction drawSpeaker(cx, cy, mainHue, accentHue, pump) {\n  push(); // keeps the styles used here from leaking into the rest of the poster\n \n  // box\n  stroke(mainHue, 30, 100);\n  strokeWeight(4);\n  fill(270, 70, 12);\n  rect(cx - 60, cy - 60, 120, 120, 8);\n \n  // corner screws\n  noStroke();\n  fill(accentHue, 40, 100);\n  for (const [sx, sy] of SCREW_OFFSETS) {\n    circle(cx + sx, cy + sy, 5);\n  }\n \n  // woofer: outer surround, pumping cone and dust cap\n  const wooferY = cy; // centered in the cabinet\n  stroke(mainHue, 50, 100);\n  strokeWeight(3);\n  fill(250, 80, 20);\n  circle(cx, wooferY, 74);\n  noStroke();\n  fill(mainHue, 80, 95);\n  circle(cx, wooferY, map(pump, 20, 100, 26, 68)); // grows up to almost touch the outer line\n  fill(accentHue, 70, 100);\n  circle(cx, wooferY, map(pump, 20, 100, 8, 16));\n \n  pop();\n}\n \n// current color from the mouse: slides from blue to pink as the mouse moves left to right\nfunction getHue() {\n  return map(mouseX, 0, width, HUE_MIN, HUE_MAX);\n}\n \n// opposite end of the blue-to-pink range, used for accents\nfunction getAccentHue(mainHue) {\n  return HUE_MIN + HUE_MAX - mainHue;\n}\n \n// adds one ripple that takes the colors the speakers have right now\nfunction addRipple() {\n  const mainHue = getHue();\n  ripples.push({ radius: RIPPLE_START, mainHue: mainHue, accentHue: getAccentHue(mainHue) });\n  lastRippleFrame = frameCount;\n}\n \n// a click starts a ripple right away\nfunction mousePressed() {\n  addRipple();\n}\n \n// holding the mouse down keeps the bass going: a new ripple every RIPPLE_INTERVAL frames\nfunction spawnRipplesWhileHeld() {\n  if (mouseIsPressed && frameCount - lastRippleFrame >= RIPPLE_INTERVAL) {\n    addRipple();\n  }\n}\n \n// draws every ripple as two glowing rings (main color and accent color) that expand from each\n// woofer and fade out. They are clipped to the big middle panel so they never spill outside it.\nfunction drawRipples() {\n  push();\n  drawingContext.beginPath();\n  drawingContext.rect(40, 200, 520, 395); // same rectangle as the middle panel\n  drawingContext.clip();\n \n  noFill();\n  strokeWeight(4);\n  for (const ripple of ripples) {\n    const fade = map(ripple.radius, RIPPLE_START, RIPPLE_MAX, 1, 0, true); // 1 = solid, 0 = invisible\n    const accentRadius = ripple.radius - RIPPLE_LAG;\n    for (let i = 0; i < circleX.length; i++) {\n      stroke(ripple.mainHue, 80, 100, fade);\n      circle(circleX[i], circleY[i], ripple.radius * 2);\n      if (accentRadius >= RIPPLE_START) { // the accent ring only appears once it is outside the woofer\n        stroke(ripple.accentHue, 80, 100, fade);\n        circle(circleX[i], circleY[i], accentRadius * 2);\n      }\n    }\n    ripple.radius += RIPPLE_SPEED;\n  }\n  pop();\n \n  // keep only the ripples that are still visible\n  ripples = ripples.filter(ripple => ripple.radius < RIPPLE_MAX);\n}\n \n// decorative white dots around the top RAVE text\nfunction drawDots() {\n  noStroke();\n  fill(255);\n  for (const [x, y, d] of dots) {\n    circle(x, y, d);\n  }\n}", "assets": {"Assets/Rave Pic.jpg": {"mime": "image/webp", "b64": ""}}});
